class Solution:

	def minVal(self, a, b):
		num_set_bits_b = bin(b)[2:].count('1')
		a_bin_arr = list(bin(a)[2:])
		ans = ''
		for i in a_bin_arr:
			if i == '1' and num_set_bits_b:
				num_set_bits_b -= 1
				ans += '1'
			else:
				ans += '0'
		i = 1
		ans = list(ans)
		while num_set_bits_b:
			if a_bin_arr[-i] != '1':
				ans[-i] = '1'
				num_set_bits_b -= 1
			i += 1
		ans = ''.join(ans)
		return int(ans, 2)
